class Solution {
public:
    int maxSubarraySumCircular(vector<int>& nums) {
        int total = 0, maxEnd = 0, minEnd = 0;
        int bestMax = INT_MIN, bestMin = INT_MAX;
        for (int x : nums) {
            maxEnd = max(x, maxEnd + x);
            minEnd = min(x, minEnd + x);
            bestMax = max(bestMax, maxEnd);
            bestMin = min(bestMin, minEnd);
            total += x;
        }
        return bestMax < 0 ? bestMax : max(bestMax, total - bestMin);
    }
};
